          and _is_int(value.get("number")) and value["number"] >= 1
          and set(value.keys()) <= {"owner", "number"})
    if not ok:
        errors.append(_note("project", "project は {\"owner\": <文字列>, \"number\": <1 以上の整数>} の形"))
