import os
import re
import subprocess

from issue_dispatch import config

GITHUB_HOST = "github.com"
GITHUB_HOST_ALIASES = ("github.com", "ssh.github.com")  # GitHub が案内する SSH の接続先 (ポート 443) も同じ host とみなす

