print('items:', len(p['items']['nodes']), 'hasNext:', p['items']['pageInfo']['hasNextPage'], 'rate:', d['data']['rateLimit'])
for n in p['items']['nodes']:
    c=n['content']; fv={f['field']['name']:(f.get('name') or f.get('text')) for f in n['fieldValues']['nodes'] if f}
