ROLES = {"manager": "管理のセッション", "worker": "作業のセッション"}
_ROLE_OF = {v: k for k, v in ROLES.items()}
MANAGER_KINDS = ("割り当て", "開始可", "待機", "解放", "引き継ぎ", "停滞", "依存の待ち", "依存の解消", "依頼")
