def _file_key(f):
    return (f["path"], None if f["units"] is None else frozenset(tuple(u) for u in f["units"]))


def same_files(a, b):
    """2 つの宣言のファイルと節が同じか (並びは問わない)。"""
    return {_file_key(f) for f in a["files"]} == {_file_key(f) for f in b["files"]}


def _comment_id(value, what):
