    if kind == "依頼" and request_kind not in REQUEST_KINDS:
        raise ValueError(f"依頼の種類は {', '.join(REQUEST_KINDS)} のどれか: {request_kind!r}")
    keys = _shape(kind, request_kind)
    required = [k.rstrip("?") for k in keys if not k.endswith("?")]
