    if lost and d.get("wait") and any(r.get("kind") == "利用者の答え" for r in d["wait"]["reasons"]):
        questions.append(_question(item, "user-answer-lost", declaration=d["judged"]["comment_id"] if d.get("judged") else None, record_lost=True))
